CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_records (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id TEXT, session_id TEXT, turn_id TEXT, occurred_at TEXT NOT NULL, event_type TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)));
CREATE TRIGGER IF NOT EXISTS audit_records_no_update BEFORE UPDATE ON audit_records BEGIN SELECT RAISE(ABORT, 'audit records are immutable'); END;
CREATE TRIGGER IF NOT EXISTS audit_records_no_delete BEFORE DELETE ON audit_records BEGIN SELECT RAISE(ABORT, 'audit records are immutable'); END;
CREATE TABLE IF NOT EXISTS session_content (session_id TEXT NOT NULL, content_sequence INTEGER NOT NULL, occurred_at TEXT NOT NULL, event_type TEXT NOT NULL, payload_json TEXT NOT NULL CHECK(json_valid(payload_json)), PRIMARY KEY(session_id, content_sequence));
CREATE TABLE IF NOT EXISTS session_sequences (session_id TEXT PRIMARY KEY CHECK(length(session_id)>0), next_content_sequence INTEGER NOT NULL CHECK(next_content_sequence>0));
CREATE TABLE IF NOT EXISTS client_sync (connection_id TEXT NOT NULL, session_id TEXT NOT NULL, content_sequence INTEGER NOT NULL, expires_at TEXT NOT NULL, PRIMARY KEY(connection_id, session_id));
CREATE TABLE IF NOT EXISTS user_settings (key TEXT PRIMARY KEY, value_json TEXT NOT NULL CHECK(json_valid(value_json)), updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS secret_records (secret_id TEXT PRIMARY KEY, provider_id TEXT NOT NULL, ciphertext BLOB NOT NULL, nonce BLOB NOT NULL, algorithm TEXT NOT NULL, key_version INTEGER NOT NULL, created_at TEXT NOT NULL, invalidated_at TEXT);
CREATE TABLE IF NOT EXISTS projects (project_id TEXT PRIMARY KEY CHECK(length(project_id)>0), canonical_root TEXT NOT NULL UNIQUE CHECK(length(canonical_root)>0), display_name TEXT NOT NULL CHECK(length(display_name)>0), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, last_opened_at TEXT NOT NULL, archived_at TEXT);
CREATE TABLE IF NOT EXISTS sessions (session_id TEXT PRIMARY KEY CHECK(length(session_id)>0), project_id TEXT REFERENCES projects(project_id) ON DELETE RESTRICT, title TEXT, model_id TEXT, status TEXT NOT NULL CHECK(status IN ('active','archived')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, last_activity_at TEXT NOT NULL, archived_at TEXT, CHECK((status='active' AND archived_at IS NULL) OR (status='archived' AND archived_at IS NOT NULL)));
CREATE TABLE IF NOT EXISTS turns (turn_id TEXT PRIMARY KEY CHECK(length(turn_id)>0), session_id TEXT NOT NULL REFERENCES sessions(session_id) ON DELETE CASCADE, submission_idempotency_key TEXT, state TEXT NOT NULL CHECK(state IN ('admitted','queued','preparing','calling_model','resolving_calls','compacting','completed','failed','cancelled','interrupted')), model_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, completed_at TEXT, error_code TEXT, input_tokens INTEGER NOT NULL DEFAULT 0, output_tokens INTEGER NOT NULL DEFAULT 0, total_tokens INTEGER NOT NULL DEFAULT 0, UNIQUE(session_id, submission_idempotency_key));
CREATE TABLE IF NOT EXISTS tool_calls (turn_id TEXT NOT NULL REFERENCES turns(turn_id) ON DELETE CASCADE, tool_call_id TEXT NOT NULL CHECK(length(tool_call_id)>0), name TEXT NOT NULL CHECK(length(name)>0), state TEXT NOT NULL CHECK(state IN ('requested','validating','policy_check','denied','awaiting_approval','authorized','executing','succeeded','failed','timed_out','unknown_completion','reconciling')), ordinal INTEGER CHECK(ordinal IS NULL OR ordinal>=0), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, completed_at TEXT, error_code TEXT, PRIMARY KEY(turn_id,tool_call_id));
CREATE TABLE IF NOT EXISTS approval_requests (approval_id TEXT PRIMARY KEY, project_id TEXT, session_id TEXT NOT NULL, turn_id TEXT NOT NULL, tool_call_id TEXT NOT NULL, operation TEXT NOT NULL, arguments_json TEXT NOT NULL CHECK(json_valid(arguments_json)), idempotency_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL CHECK(status IN ('pending','approved','denied')), decision TEXT, decision_source TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS suspended_turns (approval_id TEXT PRIMARY KEY REFERENCES approval_requests(approval_id), session_id TEXT NOT NULL, turn_id TEXT NOT NULL, snapshot_json TEXT NOT NULL CHECK(json_valid(snapshot_json)), status TEXT NOT NULL CHECK(status IN ('pending','resuming','completed','denied','failed')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS turn_submissions (session_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','completed','failed')), response_json TEXT CHECK(response_json IS NULL OR json_valid(response_json)), error_json TEXT CHECK(error_json IS NULL OR json_valid(error_json)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, turn_id TEXT, input_json TEXT CHECK(input_json IS NULL OR json_valid(input_json)), model_id TEXT, admitted_at TEXT, started_at TEXT, completed_at TEXT, PRIMARY KEY(session_id,idempotency_key));
CREATE TABLE IF NOT EXISTS checkpoint_manifests (manifest_id TEXT PRIMARY KEY CHECK(length(manifest_id)>0), session_id TEXT NOT NULL REFERENCES sessions(session_id) ON DELETE CASCADE, turn_id TEXT REFERENCES turns(turn_id) ON DELETE SET NULL, status TEXT NOT NULL CHECK(status IN ('available','restoring','restored','partial','conflict','expired')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, expires_at TEXT NOT NULL, restored_at TEXT);
CREATE TABLE IF NOT EXISTS checkpoints (checkpoint_id TEXT PRIMARY KEY CHECK(length(checkpoint_id)>0), session_id TEXT NOT NULL REFERENCES sessions(session_id) ON DELETE CASCADE, turn_id TEXT, tool_call_id TEXT, relative_path TEXT, status TEXT NOT NULL CHECK(status IN ('available','restored','invalidated')), created_at TEXT NOT NULL, restored_at TEXT, invalidated_at TEXT, manifest_id TEXT REFERENCES checkpoint_manifests(manifest_id) ON DELETE CASCADE, ordinal INTEGER CHECK(ordinal IS NULL OR ordinal>=0), FOREIGN KEY(turn_id,tool_call_id) REFERENCES tool_calls(turn_id,tool_call_id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS session_messages (message_id TEXT PRIMARY KEY CHECK(length(message_id)>0), session_id TEXT NOT NULL REFERENCES sessions(session_id) ON DELETE CASCADE, turn_id TEXT, content_sequence INTEGER NOT NULL CHECK(content_sequence>0), role TEXT NOT NULL CHECK(role IN ('user','assistant','tool')), message_json TEXT NOT NULL CHECK(json_valid(message_json)), usage_json TEXT CHECK(usage_json IS NULL OR json_valid(usage_json)), created_at TEXT NOT NULL, UNIQUE(session_id,content_sequence));
CREATE TABLE IF NOT EXISTS setting_records (scope TEXT NOT NULL CHECK(scope IN ('user','project','session')), scope_id TEXT NOT NULL CHECK(length(scope_id)>0), key TEXT NOT NULL CHECK(length(key)>0), value_json TEXT NOT NULL CHECK(json_valid(value_json)), updated_at TEXT NOT NULL, PRIMARY KEY(scope,scope_id,key));
CREATE INDEX IF NOT EXISTS projects_last_opened_idx ON projects(archived_at,last_opened_at DESC);
CREATE INDEX IF NOT EXISTS sessions_project_activity_idx ON sessions(project_id,status,last_activity_at DESC,session_id);
CREATE INDEX IF NOT EXISTS turns_session_created_idx ON turns(session_id,created_at DESC,turn_id);
CREATE INDEX IF NOT EXISTS tool_calls_turn_state_idx ON tool_calls(turn_id,state);
CREATE INDEX IF NOT EXISTS approval_requests_session_status_idx ON approval_requests(session_id,status,created_at);
CREATE INDEX IF NOT EXISTS audit_records_project_time_idx ON audit_records(project_id,occurred_at);
CREATE INDEX IF NOT EXISTS audit_records_session_time_idx ON audit_records(session_id,occurred_at);
CREATE INDEX IF NOT EXISTS audit_records_turn_time_idx ON audit_records(turn_id,occurred_at);
CREATE INDEX IF NOT EXISTS session_content_session_type_seq_idx ON session_content(session_id,event_type,content_sequence);
CREATE INDEX IF NOT EXISTS session_content_session_seq_durable_idx ON session_content(session_id,content_sequence) WHERE event_type NOT IN ('assistant.delta','reasoning.delta','tool.input.delta');
CREATE INDEX IF NOT EXISTS checkpoint_manifests_session_status_idx ON checkpoint_manifests(session_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS checkpoints_manifest_ordinal_idx ON checkpoints(manifest_id,ordinal);
CREATE UNIQUE INDEX IF NOT EXISTS checkpoint_manifests_turn_idx ON checkpoint_manifests(turn_id) WHERE turn_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS turn_submissions_session_turn_idx ON turn_submissions(session_id,turn_id) WHERE turn_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS turn_submissions_status_admitted_idx ON turn_submissions(status,admitted_at,session_id,idempotency_key);
CREATE INDEX IF NOT EXISTS session_messages_session_role_seq_idx ON session_messages(session_id,role,content_sequence);
